","new":"def parse_port(text):
    if not isinstance(text, str) or not text:
        return None
    port = 0
    for digit in text:
        if not '0' <= digit <= '9':
            return None
        port = port * 10 + ord(digit) - ord('0')
        if port > 65535:
            return None
    return port if port >= 1 else None
